import{_ as a,c as r,o,ae as t,j as i}from"./chunks/framework.tuuL-SzM.js";const n="/reel-it-in/main-game-start.png",m=JSON.parse('{"title":"Reel it in!","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"projects/reel-it-in.md","filePath":"projects/reel-it-in.md","lastUpdated":1758924781000}'),l={name:"projects/reel-it-in.md"};function s(h,e,c,d,p,g){return o(),r("div",null,e[0]||(e[0]=[t('<h1 id="reel-it-in" tabindex="-1">Reel it in! <a class="header-anchor" href="#reel-it-in" aria-label="Permalink to &quot;Reel it in!&quot;">​</a></h1><h2 id="play-now" tabindex="-1"><a href="https://gelearthur.itch.io/reelitin" target="_blank" rel="noreferrer"><strong>Play now</strong></a> <a class="header-anchor" href="#play-now" aria-label="Permalink to &quot;[**Play now**](https://gelearthur.itch.io/reelitin)&quot;">​</a></h2>',2),i("iframe",{width:"560",height:"315",src:"https://www.youtube-nocookie.com/embed/xz8vwJNW9XA",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""},null,-1),t('<p>Reel It In is a chaotic 1v3 couch multiplayer game where players use a fishing rod to pull, push, and sabotage each other!</p><p><img src="'+n+'" alt="GameScreen"></p><h2 id="gameplay" tabindex="-1">Gameplay <a class="header-anchor" href="#gameplay" aria-label="Permalink to &quot;Gameplay&quot;">​</a></h2><p>Our restrictions for this game was that it needed to be a couch co-op game. The inspiration came from the niche minecraft mechanic where you can hook other players with the fishing rod and pull them towards you.</p><p>The goal for our game was to avoid snow balls fired by a cannon that is controlled by one of the players. When a player gets hit by the snow ball the cannon player and the field player swap places.</p><h2 id="play-testing-is-key" tabindex="-1">Play testing is key <a class="header-anchor" href="#play-testing-is-key" aria-label="Permalink to &quot;Play testing is key&quot;">​</a></h2><p>One big lesson I learned is <strong>PLAY TEST</strong>, <strong>PLAY TEST</strong> and <strong>PLAY TEST</strong>. In the second week we already had a working game. In hindsight we should have done a play test. If you are working on a project your mind gets fixated on one thing. Without external feedback we didn&#39;t realize that the game wasn&#39;t fun enough. After we worked on the game for 7 weeks the project was already past prototyping but it still didn&#39;t feel right. The reeling was clunky and the goal was not clear.</p><p>Our solution was to do a play test. We found multiple issues with game design. We wrote down all the problems so we could discuss it with the team. I convinced the team that we needed to do a big change. This is never fun as you are throwing away work. Check out the <a href="https://gelearthur.itch.io/reelitin/devlog/934265/devlog-7-quite-the-turn" target="_blank" rel="noreferrer">dev log week 7 quite the turn</a>. After some more play testing we got the fun factor in the game.</p><h2 id="links" tabindex="-1">links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;links&quot;">​</a></h2><ul><li><a href="https://gelearthur.itch.io/reelitin" target="_blank" rel="noreferrer">itch</a></li><li><a href="https://gelearthur.itch.io/reelitin/devlog" target="_blank" rel="noreferrer">devlog</a></li></ul>',10)]))}const w=a(l,[["render",s]]);export{m as __pageData,w as default};
